function M.replace_line(bufnr, line_num, replacement)
  return M.replace_lines(bufnr, line_num, line_num, { replacement })
end

function M.find_lua_files(dir)
  return fn.globpath(dir, "**/*.lua", false, true)
end

function M.register(opts)
  composer.verb(opts.name, {
    desc = str_fmt("Migration tool: %s", opts.name),
    range = true,
    routes = {
      {
        path = {},
        args = { { name = "mode", type = "MIGRATE_SCOPE", optional = true } },
        range = true,
        desc = str_fmt("Migration tool: %s", opts.name),
        run = function(ctx)
          dispatch(opts, ctx.raw)
        end,
      },
    },
  })
end

function M.get()
  return M.options
end

local function show_picker_impl(matches)
  picker.show(matches, {
    title = "Migrate vim.highlight -> vim.hl",
    single_apply = true,

    format_entry = function(match)
      local location = match.fname and (vim.fn.fnamemodify(match.fname, ":t") .. ":" .. match.lnum)
        or ("buf:" .. match.bufnr .. ":" .. match.lnum)

      return str_fmt("%s  %s", location, match.text:sub(1, 60))
    end,

    format_preview = function(match)
      return { match.migrated }
    end,

    on_apply = function(selections)
      apply_matches(selections)
      notify.info(str_fmt("Applied %d migration(s)", #selections))
    end,
  })
end

function M.enable()
  command.register({
    name = "MigrateHl",
    scan_range = scan_range,
    scan_buffer = scan_buffer,
    scan_cwd = scan_cwd,
    apply_matches = apply_matches,
    show_picker = show_picker_impl,
  })
end

function M.migrate_line(line)
  return (line:gsub("vim%.highlight%.", "vim.hl."))
end

